import{z as p,x as B,o as r,c as d,q as E,j as s,D as n,d as l,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"平面图直觉","description":"","frontmatter":{"title":"平面图直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/planar-graph.md","filePath":"cs/planar-graph.md","lastUpdated":1791063341000}'),m={name:"cs/planar-graph.md"};function A(f,a,D,h,u,C){const t=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=E('<h1 id="平面图直觉" tabindex="-1">平面图直觉 <a class="header-anchor" href="#平面图直觉" aria-label="Permalink to &quot;平面图直觉&quot;">​</a></h1><div class="epigraph"><p>能画在平面上使边只在顶点相交，则边数相对顶点数是线性的；稀疏不是偶然，是欧拉公式在管着。</p><footer>—— 据 Euler 多面体公式；Cormen, Leiserson, Rivest and Stein 对平面图 $m=O(n)$ 的用法 整理</footer></div><p><a href="/cs/dag-repr">上一课</a>把有向无环钉成可线性扩展的依赖图，数据结构课的表示轴在 DAG 结束。本课不重讲拓扑序，也不从「图是什么」另起。缺口是另一类全局形状：平面性给出 \\(m\\le 3n-6\\)（简单连通平面，\\(n\\ge 3\\)）这类线性边数，解释道路网、网格为什么落在稀疏假设里。算法课下一课才用循环不变式；本课只交直觉与这条界，不跑平面性判定。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>稀疏课写 \\(m\\ll n^2\\) 是工作假设。平面图把它变成定理：欧拉 \\(n-m+f=2\\)（连通平面嵌入，含外脸），每张脸至少 3 条边、每边贴 2 脸，得 \\(2m\\ge 3f\\)，消掉 \\(f\\) 即 \\(m\\le 3n-6\\)。缺口不是新的 CSR 字段，而是<strong>何时可以默认度数的平均值 \\(\\le 6\\)</strong>，从而「扫所有边」与「扫所有点」同阶。</p><p>\\(K_5\\)、\\(K_{3,3}\\) 非平面，Kuratowski：含它们的细分则非平面。本课点名，不证。</p><p><span class="marginnote">平面嵌入是画法；同一抽象图可以有的能画、有的不能。数据结构存的仍是邻接，不自动带嵌入。</span></p><p><span class="marginnote">数字实例：\\(m\\le 3n-6\\) 直接给平均度 \\(2m/n\\le 6-12/n\\lt 6\\)。取 \\(n=1000\\)：边至多 2994 条，平均度至多 5.988。所以「摸一遍所有边」的成本和「摸一遍所有点」同阶——这就是平面输入能当稀疏假设用的原因。</span></p><p><span class="marginnote">\\(K_5\\)（5 点两两相连）和 \\(K_{3,3}\\)（3 对 3 完全二分）是平面性的两块绊脚石。直觉类比：5 个人每两人握一次手共 10 条手臂，在桌面上怎么摆都必然有两根交叉；Kuratowski 说的是，任何非平面图里都藏着把这两块石头加点拉长后的影子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>表示仍用 CSR 或邻接表。若输入承诺平面，算法可用 \\(O(n)\\) 边的界写时间；若不承诺，最坏仍 \\(m=\\Theta(n^2)\\)。对偶：脸当顶点、相邻脸连边——附录，主干只承认脸的计数出现在欧拉式里。</p>',11)),(r(),s(i,null,{default:n(()=>[o(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PL%5B%22%E5%B9%B3%E9%9D%A2%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20EU%5B%22n%20%E2%88%92%20m%20%2B%20f%20%3D%202%22%5D%0A%20%20EU%20--%3E%20BND%5B%22m%20%E2%89%A4%203n%20%E2%88%92%206%22%5D%0A%20%20BND%20--%3E%20SP%5B%22%E5%B9%B3%E5%9D%87%E5%BA%A6%20%EF%BC%9C%206%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 DAG：无环不管能不能画平；平面不管有没有向。网格两者都常满足，道路网近似平面（立交是少数例外）。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"平均度有界让「每个点处理 \\(\\deg(v)\\)」的算法在平面输入上近线性。最短路、最小生成树的堆操作次数仍跟 \\(m\\) 走，因而也线性档。这不是平面专用算法（那些用 r-division 的附录），只是稀疏参数被几何钉死。",-1)),a[6]||(a[6]=e("p",null,"\\(m\\le 3n-6\\) 这条界，数数是怎么数的？",-1)),(r(),s(i,null,{default:n(()=>[o(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20EU%5B%22%E6%AC%A7%E6%8B%89%EF%BC%9An%20%E2%88%92%20m%20%2B%20f%20%3D%202%22%5D%20--%3E%20FC%5B%22%E6%AF%8F%E5%BC%A0%E8%84%B8%E8%87%B3%E5%B0%91%E8%B4%B4%203%20%E6%9D%A1%E8%BE%B9%22%5D%0A%20%20FC%20--%3E%20C1%5B%22%E8%84%B8%E7%9A%84%E8%BE%B9%E6%AC%A1%E5%90%88%E8%AE%A1%20%E2%89%A5%203f%22%5D%0A%20%20EC%5B%22%E6%AF%8F%E6%9D%A1%E8%BE%B9%E6%81%B0%E5%A5%BD%E8%B4%B4%202%20%E5%BC%A0%E8%84%B8%22%5D%20--%3E%20C2%5B%22%E8%84%B8%E7%9A%84%E8%BE%B9%E6%AC%A1%E5%90%88%E8%AE%A1%20%3D%202m%22%5D%0A%20%20C1%20--%3E%20INEQ%5B%22%E6%89%80%E4%BB%A5%202m%20%E2%89%A5%203f%22%5D%0A%20%20C2%20--%3E%20INEQ%0A%20%20INEQ%20--%3E%20SUB%5B%22%E4%BB%A3%E5%85%A5%20f%20%3D%202%20%E2%88%92%20n%20%2B%20m%20%E6%B6%88%E5%8E%BB%20f%22%5D%0A%20%20SUB%20--%3E%20BND%5B%22%E6%95%B4%E7%90%86%E5%BE%97%20m%20%E2%89%A4%203n%20%E2%88%92%206%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">常见误区：把「稀疏」和「平面」画等号。随机 3-正则图同样是 \\(m=O(n)\\) 的稀疏图，却没有欧拉脸计数、也没有小分离器那套几何红利。平面带来的不只是边少，还有「画法」这个额外结构。</span></p><p>非平面的稀疏图（随机 \\(d\\)-正则）同样 \\(m=O(n)\\)，但没有欧拉脸计数；不要把稀疏与平面画等号。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现左儿子右兄弟式的嵌入数据结构，不跑 Hopcroft–Tarjan 平面性。也不把四色定理当课。循环不变式课开始后，正确性靠断言，不再靠「图画出来看起来对」。大模型、量化、光刻栏的图不在这里借用。</p><p>后课默认：谈到平面输入，可用 \\(m=O(n)\\)。数据结构课结束；算法课用不变式给循环证明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>简单平面图 \\(m=O(n)\\)，来自欧拉与脸的度数。</li><li>表示仍是稀疏邻接；平面是额外几何约束。</li><li>数据结构课收束；下一课循环不变式。</li><li>出处：欧拉公式；Cormen et al. 对平面图边数的标准推论；Kuratowski 作为非平面对照。</li></ul>',7))])}const g=p(m,[["render",A]]);export{c as __pageData,g as default};
